const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const villarricaPoint = ee.Geometry.Point([-72.23, -39.26]); // Coordinates for Villarrica, Chile
  const areaOfInterest = villarricaPoint.buffer(5000); // 5 km buffer around Villarrica

  const startDate2021 = '2021-01-01';
  const endDate2021 = '2021-12-31';

  const startDate2016 = '2016-01-01';
  const endDate2016 = '2016-12-31';

  const bandName = 'precipitation';
  const scale = 5000; // Resolution of CHIRPS is approx 5.5km, use 5km for reduction.

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY/2_0');

  const collection2021 = chirps
    .filterDate(startDate2021, endDate2021)
    .filterBounds(areaOfInterest);

  const collection2016 = chirps
    .filterDate(startDate2016, endDate2016)
    .filterBounds(areaOfInterest);

  // Check for empty collections (C1)
  const size2021 = await collection2021.size().getInfo();
  const size2016 = await collection2016.size().getInfo();

  if (size2021 === 0 || size2016 === 0) {
    console.log(`2021 Images: ${size2021}`);
    console.log(`2016 Images: ${size2016}`);
    console.log("C1");
    return;
  }

  // 3. Processing: Calculate total precipitation for each period
  const totalPrecipitation2021 = collection2021.select(bandName).sum();
  const totalPrecipitation2016 = collection2016.select(bandName).sum();

  // Reduce regions to get the precipitation values
  const precip2021_reduced = await totalPrecipitation2021.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: areaOfInterest,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName).getInfo();

  const precip2016_reduced = await totalPrecipitation2016.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: areaOfInterest,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName).getInfo();

  // Check for C3 (Calculation Failure: None, NaN, or invalid)
  if (precip2021_reduced === null || isNaN(precip2021_reduced) ||
      precip2016_reduced === null || isNaN(precip2016_reduced)) {
    console.log(`2021 Precipitation: ${precip2021_reduced}`);
    console.log(`2016 Precipitation: ${precip2016_reduced}`);
    console.log("C3");
    return;
  }

  // 4. Validate valid pixels after reduction
  // A simple count reducer would be needed for a strict C2 check on pixels,
  // but sum().reduceRegion().get(bandName).getInfo() returning a non-null/NaN
  // value implies there were valid pixels for precipitation. If precipitations were 0,
  // it would be a valid zero, not C2.

  // 5. Comparison and Final Answer
  console.log(`2021 Images: ${size2021}`);
  console.log(`2016 Images: ${size2016}`);
  console.log(`Total Rainfall 2021: ${precip2021_reduced.toFixed(2)} mm`);
  console.log(`Total Rainfall 2016: ${precip2016_reduced.toFixed(2)} mm`);

  if (precip2021_reduced > precip2016_reduced) {
    console.log("A"); // Yes, more rainfall in 2021
  } else {
    console.log("B"); // No, not more rainfall in 2021 (or equal)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
